def once(n): return ' Sólo puedes usar este efecto de "%s" una vez por turno.' % n
def each(n): return ' Sólo puedes usar cada efecto de "%s" una vez por turno.' % n
def act1(n): return ' Sólo puedes activar 1 "%s" por turno.' % n
S = '"Spellbook"'
SM = 'Mágica ' + S
SMS = 'Mágicas ' + S
SC = 'monstruo de Tipo Lanzador de Conjuros'
ONLYSB = ' No puedes activar ninguna Carta Mágica el turno en que actives esta carta, excepto ' + SMS + '.'
ES = {
"Empress of Prophecy": '2 monstruos de Tipo Lanzador de Conjuros de Nivel 5\nEsta carta gana 300 ATK por cada Material Xyz acoplado a un monstruo que controles. Una vez por turno: puedes desacoplar 1 Material Xyz de esta carta; baraja tu Deck, después excava las 5 cartas superiores de tu Deck, destruye monstruos en el Campo hasta el número de cartas ' + S + ' excavadas y, además, después de eso, coloca las cartas excavadas en la parte superior del Deck en cualquier orden.',
"Defender, the Magical Knight": 'Si esta carta es Invocada de Modo Normal: pon 1 Contador de Magia en ella (máx. 1). Una vez por turno, si uno o más monstruos de Tipo Lanzador de Conjuros en el Campo fueran a ser destruidos, puedes quitar en su lugar 1 Contador de Magia de tu Campo por cada uno de esos monstruos.',
"Armor Exe": 'Esta carta no puede atacar en el mismo turno en que sea Invocada de Modo Normal, por Volteo o de Modo Especial. Durante cada una de tus Standby Phases y de las de tu adversario, quita 1 Contador de Magia de tu lado del Campo. Si no lo haces, destruye esta carta.',
"Reaper of Prophecy": 'Cuando esta carta sea Invocada de Modo Normal o Especial: puedes activar este efecto; aplica tantos efectos como sea posible, según el número de Cartas ' + SMS + ' con nombres diferentes en tu Cementerio.' + once("Reaper of Prophecy") + '\n● 3 o más: esta carta gana 600 ATK.\n● 4 o más: añade a tu mano 1 Carta ' + SM + ' de tu Deck.\n● 5 o más: Invoca de Modo Especial 1 ' + SC + ' de OSCURIDAD de Nivel 5 o mayor de tu Deck.',
"Spellbook of the Grand Circle": 'Añade a tu mano 4 monstruos "Charmer" con Atributos diferentes de tu Deck, Cementerio y/o de entre tus cartas desterradas y, después, baraja en el Deck 2 cartas de tu mano. Puedes desterrar esta carta de tu Cementerio; Invoca por Fusión 1 Monstruo de Fusión desde tu Extra Deck, usando monstruos "Charmer" o "Familiar-Possessed" de tu mano o Campo; además, tu adversario no puede activar cartas ni efectos cuando un monstruo sea Invocado por Fusión de esta forma.' + each("Spellbook of the Grand Circle"),
"Strength of Prophecy": 'Una vez por turno: puedes barajar en tu Deck 1 Carta ' + SM + ' de tu Cementerio para seleccionar 1 ' + SC + ' boca arriba en el Campo; aumenta su Nivel en 1 y su ATK en 500.',
"Spellbook Magician of Prophecy": 'Si esta carta es Invocada de Modo Normal o volteada boca arriba: añade a tu mano 1 ' + SM + ' de tu Deck.',
"Magical Contract Door": 'Añade 1 Carta Mágica de tu mano a la mano de tu adversario y, después, añade a tu mano 1 monstruo de OSCURIDAD de Nivel 7 u 8 de tu Deck.',
"Spellbook Library of the Heliosphere": 'Si tienes 5 o más Cartas ' + SMS + ' en tu Cementerio: excava las 2 cartas superiores de tu Deck, añade a tu mano cualquier Carta ' + SM + ' excavada y, además, baraja las demás cartas en el Deck.' + act1("Spellbook Library of the Heliosphere") + ONLYSB,
"Supreme Arcanite Magician": '1 Monstruo de Sincronía de Tipo Lanzador de Conjuros + 1 ' + SC + '\nEste monstruo sólo puede ser Invocado de Modo Especial mediante una Invocación por Fusión (desde el Extra Deck). Cuando esta carta sea Invocada por Fusión, pon 2 Contadores de Magia en ella. Esta carta gana 1000 ATK por cada Contador de Magia en ella. Una vez por turno, puedes quitar 1 Contador de Magia de tu lado del Campo para activar 1 de los siguientes efectos:\n● Selecciona 1 carta en el Campo y destrúyela.\n● Roba 1 carta.',
"Type Zero Magic Crusher": 'Descarta 1 Carta Mágica de tu mano para infligir 500 puntos de daño a los Life Points de tu adversario.',
"Hidden Spellbook": 'Durante tu turno: selecciona 2 Cartas Mágicas en tu Cementerio; baraja esos objetivos en el Deck.',
"Spellbook of Knowledge": 'Manda al Cementerio 1 ' + SC + ' que controles, o 1 otra carta ' + S + ' de tu mano o boca arriba de tu Campo, excepto "Spellbook of Knowledge" y, si lo haces, roba 2 cartas.' + act1("Spellbook of Knowledge"),
"Spellbook of Power": 'Selecciona 1 ' + SC + ' que controles; este turno, gana 1000 ATK. Y, si lo hace, cada vez que destruya en batalla un monstruo del adversario este turno: puedes añadir a tu mano 1 ' + SM + ' de tu Deck.' + act1("Spellbook of Power"),
"Time Wizard of Tomorrow": '"Time Wizard" + 1 Monstruo de Efecto\nUna vez por turno, mientras controles esta carta Invocada por Fusión: puedes lanzar una moneda y elegir un resultado. Destruye tantos monstruos en el Campo como sea posible y, si lo haces, inflige daño igual a la mitad del ATK original total de los monstruos boca arriba destruidos. Si acertaste el resultado de la moneda, tu adversario recibe el daño; si fallaste, recibes tú el daño.',
"Justice of Prophecy": 'Durante tu End Phase, si has activado previamente una Carta ' + SM + ' este turno: puedes desterrar esta carta del Campo; añade a tu mano desde tu Deck 1 ' + SC + ' de LUZ u OSCURIDAD de Nivel 5 o mayor y 1 Carta ' + SM + '.' + once("Justice of Prophecy"),
"World of Prophecy": 'Cuando esta carta sea Invocada de Modo Especial por el efecto de un ' + SC + ' o de una Carta ' + SM + ': puedes seleccionar 2 Cartas ' + SMS + ' en tu Cementerio; añade esos objetivos a tu mano. No puedes Invocar de Modo Especial otros monstruos durante el turno en que actives este efecto. Cuando añadas una o más cartas a tu mano por este efecto: puedes revelar 4 Cartas ' + SMS + ' con nombres diferentes en tu mano; destruye todas las demás cartas en el Campo.',
"Mega Ton Magical Cannon": 'Quita 10 Contadores de Magia de tu Campo; destruye todas las cartas que controle tu adversario.',
"Magical Merchant": 'VOLTEO: excava cartas de la parte superior de tu Deck hasta excavar una Mágica/Trampa y, después, añade esa carta a tu mano; además, manda al Cementerio las cartas restantes.',
"The Grand Spellbook Tower": 'Una vez por turno, durante tu Standby Phase, si tienes un ' + SC + ' en tu lado del Campo o en tu Cementerio: puedes colocar en la parte inferior de tu Deck 1 Carta ' + SM + ' de tu Cementerio, excepto "The Grand Spellbook Tower" y, después, robar 1 carta. Cuando esta carta en tu posesión sea destruida por tu adversario y mandada a tu Cementerio: puedes Invocar de Modo Especial desde tu mano o Deck 1 ' + SC + ' cuyo Nivel sea menor o igual que el número de Cartas ' + SMS + ' en tu Cementerio.',
"Magical Scientist": 'Paga 1000 Life Points para Invocar de Modo Especial desde tu Extra Deck 1 Monstruo de Fusión de Nivel 6 o menor en Posición de Ataque o de Defensa boca arriba. Ese Monstruo de Fusión no puede atacar directamente a los Life Points de tu adversario, y vuelve a tu Extra Deck al final del turno.',
"Amores of Prophecy": 'Una vez por turno: puedes revelar 1 Carta ' + SM + ' en tu mano; Invoca de Modo Especial 1 ' + SC + ' de Nivel 4 o menor de tu mano.',
"Spellbook Library of the Crescent": 'Si no tienes Cartas ' + SMS + ' en tu Cementerio: revela 3 Cartas ' + SMS + ' con nombres diferentes de tu Deck; tu adversario añade 1 de ellas al azar a tu mano, y baraja el resto en tu Deck.' + act1("Spellbook Library of the Crescent") + ONLYSB,
"Endymion, the Master Magician": 'Puedes Invocar esta carta de Modo Especial (desde tu mano o Cementerio) quitando 6 Contadores de Magia de un "Magical Citadel of Endymion" que controles. Si es Invocada de esta forma: selecciona 1 Mágica en tu Cementerio; añade ese objetivo a tu mano. Una vez por turno: puedes descartar 1 Mágica y, después, seleccionar 1 carta en el Campo; destruye ese objetivo.',
"Spellbook of Miracles": 'Selecciona 1 Monstruo Xyz de Tipo Lanzador de Conjuros en tu Cementerio y hasta 2 de tus Cartas ' + SMS + ' desterradas; Invoca de Modo Especial ese monstruo y, si lo haces, acóplale como Material Xyz la Carta o Cartas ' + SMS + ' seleccionadas.' + act1("Spellbook of Miracles"),
"Ebon Magician Curran": 'Durante tu Standby Phase, inflige a tu adversario 300 de daño por cada monstruo que controle.',
"Spellbook of Judgment": 'Durante la End Phase del turno en que se activó esta carta, añade a tu mano ' + SMS + ' de tu Deck, excepto "Spellbook of Judgment", hasta el número de Cartas Mágicas activadas después de la resolución de esta carta y, después, puedes Invocar de Modo Especial desde tu Deck 1 ' + SC + ' cuyo Nivel sea menor o igual que el número de cartas añadidas a tu mano por este efecto.' + act1("Spellbook of Judgment"),
"Gilti-Gearfried the Magical Steel Knight": '2 monstruos de Tipo Guerrero con Atributos diferentes\nUna vez por turno, cuando se active una carta o efecto que seleccione esta carta (Efecto Rápido): puedes negar ese efecto y, si lo haces, destruye 1 carta en el Campo. Si esta carta fue Invocada por Fusión usando sólo monstruos en el Campo como material, puede realizar un segundo ataque durante cada Battle Phase. Una vez por turno, si esta carta combate con un monstruo del adversario, durante el cálculo de daño (Efecto Rápido): puedes desterrar 1 Mágica de tu Cementerio; esta carta gana ATK igual a la mitad de su DEF actual, hasta el final de este turno.',
"Charioteer of Prophecy": 'Una vez por turno: puedes descartar 1 Carta ' + SM + ' para seleccionar 1 ' + SC + ' en tu Cementerio; añade ese objetivo a tu mano.',
"Giltia the D. Knight": '"Guardian of the Labyrinth" + "Protector of the Throne"',
"Spellbook of Life": 'Destierra 1 ' + SC + ' de tu Cementerio y revela 1 otra Carta ' + SM + ' en tu mano para seleccionar 1 ' + SC + ' en tu Cementerio; Invoca de Modo Especial ese objetivo en Posición de Ataque boca arriba y equípalo con esta carta. El Nivel del monstruo equipado aumenta en el Nivel del monstruo que fue desterrado para la activación de esta carta.' + act1("Spellbook of Life"),
"Emperor of Prophecy": 'Puedes desterrar 1 ' + SC + ' boca arriba que controles, excepto esta carta, y 1 carta ' + S + ' de tu Cementerio para seleccionar 1 monstruo boca arriba que controle tu adversario; toma el control de ese objetivo hasta la End Phase.' + once("Emperor of Prophecy") + ' Esta carta no puede atacar durante el turno en que actives este efecto.',
"Stoic of Prophecy": 'Cuando esta carta sea mandada al Cementerio: añade a tu mano 1 monstruo "Prophecy" de Nivel 3 de tu Deck.',
"Prophecy Destroyer": 'Si esta carta está en tu Cementerio: puedes desterrar 3 Cartas ' + SMS + ' de tu Cementerio; Invoca esta carta de Modo Especial desde tu Cementerio.',
"Spellbook Star Hall": 'Cada vez que se active una Carta ' + SM + ', pon 1 Contador de Magia en esta carta. Todos los monstruos de Tipo Lanzador de Conjuros que controlas ganan 100 ATK por cada Contador de Magia en esta carta. Cuando esta carta con uno o más Contadores de Magia sea destruida y mandada al Cementerio: puedes añadir a tu mano desde tu Deck 1 ' + SC + ' cuyo Nivel sea menor o igual que el número de Contadores de Magia que había en esta carta.',
"Spellbook of the Master": 'Si controlas un ' + SC + ': puedes revelar 1 otra carta ' + S + ' en tu mano y, después, seleccionar 1 Carta ' + SM + ' Normal en tu Cementerio, excepto "Spellbook of the Master"; el efecto de esta carta pasa a ser el efecto de ese objetivo.' + act1("Spellbook of the Master"),
"Spellbook of Eternity": 'Selecciona 1 de tus Cartas ' + SMS + ' desterradas, excepto "Spellbook of Eternity"; añade ese objetivo a tu mano.' + act1("Spellbook of Eternity"),
"Fool of Prophecy": 'Una vez por turno: puedes mandar al Cementerio 1 Carta ' + SM + ' de tu Deck. Durante la End Phase del turno en que esta carta activó este efecto: puedes Sacrificar esta carta; Invoca de Modo Especial 1 ' + SC + ' de OSCURIDAD de Nivel 5 o mayor de tu Deck. Debes tener 5 o más Cartas ' + SMS + ' con nombres diferentes en tu Cementerio para activar y resolver este efecto.',
"Wheel of Prophecy": 'Cuando esta carta sea Invocada de Modo Especial por el efecto de un ' + SC + ': puedes seleccionar cualquier número de tus Cartas ' + SMS + ' desterradas; barájalas en el Deck y, si lo haces, devuelve a tu Cementerio tus demás Cartas ' + SMS + ' desterradas.' + once("Wheel of Prophecy"),
"Magical Mid-Breaker Field": 'Activa esta carta al inicio de tu Main Phase 1 o 2. Durante la Main Phase 1 de cada jugador, los monstruos en el Campo no pueden ser destruidos por efectos de cartas de su adversario; además, ningún jugador puede seleccionar monstruos que controle su adversario. No puedes activar ni Colocar Cartas Mágicas de Campo.',
"Giltia the D. Knight - Soul Spear": 'Si no controlas monstruos, puedes Invocar de Modo Normal esta carta sin Sacrificar. Cuando esta carta sea Invocada de Modo Normal: puedes desterrar 1 monstruo que controle tu adversario con ATK igual o mayor que el de esta carta. Puedes descartar 1 carta; añade a tu mano 1 de los siguientes monstruos de tu Deck.\n● Dragón de OSCURIDAD de Nivel 7\n● Máquina de OSCURIDAD de Nivel 6\n● Guerrero de AGUA de Nivel 5\n' + once("Giltia the D. Knight - Soul Spear").strip(),
"White Magician Pikeru": 'Durante tu Standby Phase: ganas 400 LP por cada monstruo que controles.',
"High Priestess of Prophecy": 'Puedes revelar 3 ' + SMS + ' en tu mano; Invoca esta carta de Modo Especial desde tu mano. Una vez por turno: puedes desterrar 1 ' + SM + ' de tu mano o Cementerio y, después, seleccionar 1 carta en el Campo; destruye ese objetivo.',
"Temperance of Prophecy": 'Durante tu Main Phase, si has activado previamente una Carta ' + SM + ' este turno: puedes Sacrificar esta carta; Invoca de Modo Especial 1 ' + SC + ' de LUZ u OSCURIDAD de Nivel 5 o mayor de tu Deck. No puedes Invocar de Modo Especial otro monstruo de Nivel 5 o mayor durante el turno en que actives este efecto.',
"Spellbook of Wisdom": 'Selecciona 1 ' + SC + ' en el Campo y, después, activa 1 de estos efectos;\n● Ese monstruo boca arriba no es afectado por otros efectos de Mágicas este turno.\n● Ese monstruo boca arriba no es afectado por efectos de Trampas este turno.',
"Spellbook of Secrets": 'Añade a tu mano 1 carta ' + S + ' de tu Deck, excepto "Spellbook of Secrets".' + act1("Spellbook of Secrets"),
"Hermit of Prophecy": 'Cada vez que se active una Carta ' + SM + ', aumenta el Nivel de esta carta en 2 y su ATK en 300.',
"Hierophant of Prophecy": '2 monstruos de Tipo Lanzador de Conjuros de Nivel 7\nUna vez por turno: puedes desacoplar 1 Material Xyz de esta carta; destruye Cartas Mágicas/de Trampa que controle tu adversario, hasta el número de Cartas ' + SMS + ' en tu Cementerio.',
"Spellbook Organization": 'Mira las 3 cartas superiores de tu Deck y, después, devuélvelas a la parte superior del Deck en cualquier orden.',
"Spellbook of Fate": 'Si controlas un ' + SC + ': puedes desterrar hasta 3 ' + SMS + ' de tu Cementerio; aplica este efecto, según el número de Mágicas desterradas para la activación de esta carta.' + act1("Spellbook of Fate") + '\n● 1: devuelve a la mano 1 Mágica/Trampa Colocada en el Campo.\n● 2: cambia 1 monstruo en el Campo a Posición de Defensa boca abajo o a Posición de Ataque boca arriba.\n● 3: destierra 1 carta que controle tu adversario.',
"Magical Citadel of Endymion": 'Cada vez que se active una Carta Mágica, pon 1 Contador de Magia en esta carta cuando esa Mágica se resuelva. Si una carta con uno o más Contadores de Magia es destruida, pon sus Contadores de Magia en esta carta. Una vez por turno, si fueras a activar un efecto de carta quitando uno o más Contadores de Magia de una carta que controles, puedes quitar en su lugar ese mismo número de Contadores de Magia de esta carta. Si esta carta fuera a ser destruida, puedes quitar en su lugar 1 Contador de Magia de esta carta.',
}
